from pathlib import Path
from html import escape as e
from urllib.parse import quote
import json

ROOT = Path(__file__).resolve().parents[1]
places = {p['id']: p for p in json.loads((ROOT/'scripts/destinations.json').read_text())}

def photo(url, alt, source):
    return dict(url=url, alt=alt, source=source)

ainslie = photo('https://images.trvl-media.com/place/553248621552334752/7047caa9-9a7f-49bd-82f0-d62653f9e018.jpg', 'Canberra and Lake Burley Griffin from Mount Ainslie lookout', 'https://www.expedia.com/Mount-Ainslie-Canberra.d553248621552334752.Vacation-Attraction')
photos = {k:v['photos'] for k,v in places.items()}
photos['ainslie'] = [ainslie]
photos['balloon'] = [
    photo('https://balloonaloftcanberra.com.au/wp-content/uploads/sites/5677/2022/07/CBR-Autumn_1-1-scaled-e1660535117315.jpg?resize=360%2C240&zoom=2', 'Balloon Aloft Canberra flight above the city', 'https://balloonaloftcanberra.com.au/all-flights/sunrise-balloon-flight/'),
    photo('https://balloonaloftcanberra.com.au/wp-content/uploads/sites/5677/2020/12/choosecbr.jpg?resize=360%2C240&zoom=2', 'Hot air ballooning with Balloon Aloft Canberra', 'https://balloonaloftcanberra.com.au/all-flights/sunrise-balloon-flight/')
]
photos['rainbow'][0] = photo('https://www.snowymagazine.com.au/content/images/2025/11/g0ojZramg2vLlKAonWAW.jpg', 'Rainbow Lake and snow-gum woodland', 'https://www.snowymagazine.com.au/rainbow-lake/')
photos['newacton'][0] = photo('https://i0.wp.com/thefifthestate.com.au/wp-content/uploads/2015/04/Nishi.jpg?fit=600%2C400&ssl=1', 'Nishi building in NewActon', 'https://thefifthestate.com.au/events/tfeevents/event-news/awards-event-news/canberras-nishi-building-receives-international-acclaim/')
photos['yarrangobilly'][1] = photo('https://www.nationalparks.nsw.gov.au/-/media/npws/images/parks/kosciuszko-national-park/yarrangobilly-area/south-glory-cave/south-glory-cave-03.jpg', 'South Glory Cave at Yarrangobilly', 'https://www.nationalparks.nsw.gov.au/things-to-do/show-caves/yarrangobilly-south-glory-cave')

def a(url, label):
    return f'<a href="{e(url,quote=True)}" target="_blank" rel="noopener noreferrer">{e(label)} ↗</a>'

def maps(name):
    return a('https://www.google.com/maps/search/?api=1&query='+quote(name+', Australia'), name)

def gallery(items, label):
    return '<div class="gallery" aria-label="'+e(label)+'">'+''.join(f'<figure><a class="photo-link" href="{e(p["url"],quote=True)}" target="_blank" rel="noopener noreferrer"><img loading="lazy" decoding="async" src="{e(p["url"],quote=True)}" alt="{e(p["alt"],quote=True)}" width="600" height="476"></a><figcaption>{a(p["source"],"Photo credit and source")}</figcaption></figure>' for p in items)+'</div>'

def ps(*keys):
    return [photos[k][0] for k in keys]

days=[]
def day(id,date,num,title,stay,effort,drive,items,note,images,links,variant='both',swap=None):
    days.append(dict(id=id,date=date,num=num,title=title,stay=stay,effort=effort,drive=drive,items=items,note=note,images=images,links=links,variant=variant,swap=swap))

day('day-1','Thu 24 Dec',1,'Sydney to Canberra, via Goulburn','Canberra · 1 of 2 nights','Easy stops + optional summit walk','About 3½–4 hr driving, before lunch and baby breaks',[
('Morning','Leave Sydney and break in Goulburn. Belmore Park has picnic tables, a playground and toilets; the Big Merino is an optional separate photo stop.'),
('Afternoon','Check in, buy Christmas groceries and settle in. Choose Civic and Braddon for a short wander and early dinner.'),
('Optional lookout','Drive to Mount Ainslie summit for a city panorama if there is energy left; otherwise save it for tomorrow. Allow 30–45 minutes at the lookout.')],
'Mount Ainslie is a priority stop. Driving to the summit keeps this arrival day relaxed. The optional Kokoda summit walk is 4.5km return with 250m ascent, steep sections and steps; allow roughly 1½–2 hours plus breaks if choosing the walk instead.',
ps('goulburn','ainslie','braddon'), [('https://www.parks.act.gov.au/find-a-nature-park/canberra-nature-park/mount-ainslie-nature-reserve','Mount Ainslie access and summit track'),('https://www.nsw.gov.au/visiting-and-exploring-nsw/locations-and-attractions/belmore-park','Belmore Park')],swap=('A different city evening','Choose NewActon’s Nishi architecture or Kingston Foreshore’s waterfront promenade and dinner instead of Braddon. Pick one precinct; restaurant Christmas Eve hours need checking.'))

day('day-2','Fri 25 Dec',2,'Christmas at the Arboretum and the lake','Canberra · 2 of 2 nights','Short walks, picnic and a nap break','Local driving · allow 45–75 min across the day',[
('Morning','Explore the National Arboretum grounds and views around Dairy Farmers Hill. Take a look at the POD playground; its higher climbing pods are mainly for older children.'),
('Midday','Return for lunch and your baby’s nap. Bring Christmas food rather than depending on cafés.'),
('Afternoon','Take a short Lake Burley Griffin stroll around Commonwealth Park or the National Carillon. Add Mount Ainslie’s drive-up lookout here if you skipped it yesterday.')],
'Arboretum grounds and the POD playground are listed as open daily. The visitor centre, café and bonsai collection close on 25 December. Keep this a flexible outdoor Christmas, especially if the day is hot.',
ps('arboretum','lake','ainslie'), [('https://www.nationalarboretum.act.gov.au/visit/opening-hours','Arboretum holiday hours'),('https://www.nca.gov.au/attractions/national-carillon','National Carillon')])
days[-1]['swap'] = ('Optional sunrise balloon flight', 'If Balloon Aloft Canberra confirms a 25 December service, eligible adults can fly before a later, shorter Arboretum visit. Meet about 30 minutes before sunrise at the Hyatt Hotel Canberra; allow 3–4 hours total for a 45–60-minute flight, plus an extra hour if choosing breakfast. Minimum age is 6: your one-year-old cannot fly, so arrange a non-flying adult to care for them. Christmas availability and the exact meeting time are unconfirmed; flights depend on weather. Keep the original morning plan if it does not run.')
days[-1]['links'].extend([('https://balloonaloftcanberra.com.au/all-flights/sunrise-balloon-flight/', 'Optional Balloon Aloft flight and timing'), ('https://balloonaloftcanberra.com.au/faq/', 'Minimum age and cancellation information')])
days[-1]['images'][2] = photos['balloon'][0]

day('day-3','Sat 26 Dec',3,'Questacon, Mini Q and the journey south','Jindabyne · 1 of 4 nights','Indoor play + travel day','Canberra → Cooma → Jindabyne · about 2½ hr driving',[
('9am–noon','Visit Questacon, including Mini Q’s play space for ages 0–6. Book general admission ahead. Mini Q may use timed sessions allocated on arrival in busy periods.'),
('Lunch and drive','Have lunch, then head south. Pause in Cooma for feeding and a proper break before continuing to Jindabyne.'),
('Late afternoon','Check into an ensuite cabin or apartment, stock the kitchen and have a quiet evening.')],
'Prams park outside Mini Q; it has baby-change and feeding facilities. Snowy Hydro Discovery Centre in Cooma publishes Boxing Day hours of 9am–2pm, so save the exhibits for the return journey if leaving Canberra after lunch.',
ps('questacon','cooma','jindabyne'), [('https://www.questacon.edu.au/whats-on/exhibitions/mini-q','Mini Q facilities and sessions'),('https://www.questacon.edu.au/visiting','Questacon admission'),('https://www.snowyhydro.com.au/visit/snowy-hydro-discovery-centre/','Cooma Discovery Centre hours')],swap=('Animals or bushland instead','Replace Questacon with the National Zoo & Aquarium, allowing about 3 hours from its 9:30am opening, OR The Sanctuary at Tidbinbilla. Tidbinbilla adds access driving: allow roughly 3½–4½ hours total driving for the day plus a 2-hour visit. These replace Questacon, not additions.'))

day('day-4','Sun 27 Dec',4,'Charlotte Pass and the Snow Gums boardwalk','Jindabyne · 2 of 4 nights','400m return boardwalk · steps and exposure','About 1½–2 hr driving return from Jindabyne',[
('Morning','Drive up to Charlotte Pass. Follow the Snow Gums boardwalk for twisted alpine trees and Main Range views; allow 15–30 minutes walking before photo and baby breaks.'),
('Lunch','Stop at Sawpit Creek picnic area on the way back down.'),
('Optional extension','Walk Sawpit’s 2km Grade 3 loop if everyone is comfortable. Allow another 45–75 minutes walking, plus breaks; otherwise just picnic.')],
'A short boardwalk still needs warm layers and calm conditions. There are steps at Snow Gums, while Sawpit is an uneven carrier walk rather than a paved pram stroll. Keep the afternoon free if the morning is enough.',
ps('charlotte','sawpit','charlotte'), [('https://www.nationalparks.nsw.gov.au/things-to-do/lookouts/charlotte-pass-lookout','Charlotte Pass lookout'),('https://www.nationalparks.nsw.gov.au/-/media/visitor/files/pdf/brochures/kosciuszko-national-park/thredbo-perisher-area-walking-tracks-brochure.pdf','NPWS distances and walking notes'),('https://www.nationalparks.nsw.gov.au/things-to-do/walking-tracks/sawpit-walking-track','Sawpit walking track')])
days[-1]['images'][2]=photos['charlotte'][1]

day('day-5','Mon 28 Dec',5,'Thredbo and the Kosciuszko lookout','Jindabyne · 3 of 4 nights','4km return · exposed alpine walking','About 1–1½ hr driving return · allow 4–6 hr for the full outing',[
('Morning','Drive to Thredbo and take the scenic lift, subject to operations and confirmed infant/carrier arrangements.'),
('The walk','Follow the Kosciuszko lookout route: 4km return, about 1–2 hours walking before baby breaks. Enjoy granite formations and open alpine scenery.'),
('Afternoon','Return by lift with time before the last service, then have a relaxed village meal before heading back.')],
'Confirm how your baby and backpack carrier can travel on the lift before booking. Use the calmest forecast for this outing: swap the mountain days around if necessary. Village exploring is the lower-effort replacement if the high walk is unsuitable.',
ps('thredbo','lookout','lookout'), [('https://www.thredbo.com.au/activities/gondola-and-chairlift/','Scenic lift information'),('https://www.thredbo.com.au/activities/hikes/self-guided-hikes/','Lookout walk and lift-linked hikes'),('https://www.nationalparks.nsw.gov.au/safety/alpine-safety','Alpine weather planning')])
days[-1]['images'][2]=photos['lookout'][1]

day('day-6','Tue 29 Dec',6,'Rainbow Lake or Porcupine Rocks','Jindabyne · 4 of 4 nights','Choose one main walk; both only as a stretch','Roughly 1–1½ hr driving return for one outing; allow 1½–2 hr if combining',[
('Easier main choice','Walk Rainbow Lake: 2.5km return, 45–75 minutes published walking time. Add a picnic and allow around 2–3 hours overall.'),
('Longer main choice','Choose Porcupine Rocks instead: 5.7km return, 1½–2½ hours walking before baby breaks. Snow gums, alpine meadows and granite outcrops lead to valley views.'),
('Rest choice','A Lake Jindabyne stroll, café and accommodation break are a worthwhile alternative if you want to slow down.')],
'Both walks are priorities to consider, not an obligation to do both today. Combining them means about 8.2km and 2¼–3¾ hours published walking time, before feeds, rests and transfers: a substantial carrier day. Only do both if you already manage that load comfortably and conditions suit. Otherwise choose one or add a Jindabyne night. Avoid scrambling onto Porcupine’s rocks; Rainbow has small creek crossings.',
ps('rainbow','porcupine','jindabyne'), [('https://www.nationalparks.nsw.gov.au/things-to-do/walking-tracks/rainbow-lake-walking-track','Rainbow Lake track'),('https://www.nationalparks.nsw.gov.au/things-to-do/walking-tracks/porcupine-walk','Porcupine track and rock hazards'),('https://weareexplorers.co/porcupine-rocks/','We Are Explorers: Porcupine Rocks')])

day('day-7','Wed 30 Dec',7,'North to the Southern Highlands','Southern Highlands · 1 night','Longer transfer, easy village evening','Jindabyne → Cooma → Southern Highlands · about 4½–5½ hr driving',[
('Morning','Leave after breakfast and pause around Cooma. The Snowy Hydro Discovery Centre is an optional replacement for a longer lunch break, if timing and energy allow.'),
('On the road','Take another substantial break around Canberra or Goulburn; allow 6–8 hours elapsed for the whole journey with your baby.'),
('Evening','Check in at Berrima, Bowral or Mittagong. Pick one town for a short wander and an early dinner.')],
'This is the longest transfer. Stay in Canberra instead if you prefer a shorter day, then keep tomorrow mainly for driving home rather than forcing in the full waterfall outing.',
ps('cooma','highlands','highlands'), [('https://www.snowyhydro.com.au/visit/snowy-hydro-discovery-centre/','Discovery Centre'),('https://www.visitnsw.com/destinations/country-nsw/southern-highlands','Southern Highlands towns')],variant='base')
days[-1]['images'][2]=photos['highlands'][1]

day('day-8','Thu 31 Dec',8,'Fitzroy Falls, then home to Sydney','Home · no overnight','150m each way to the first lookout · step-free','About 2–3 hr driving total for a simple falls-to-home route',[
('Morning','Visit Fitzroy Falls. The main viewpoint is 150m from the visitor centre along a step-free walkway; allow 30–60 minutes for an unhurried stop.'),
('Optional walk','Continue along part of the West Rim track for more gorge views if time and footing suit.'),
('Lunch and home','Have lunch in a Highlands village and head to Sydney, allowing for New Year’s Eve traffic.')],
'Fitzroy is the main recommendation. Carrington Falls plus Nellies Glen is a worthwhile alternative if you want a dedicated waterfall half-day, but is not essential after Fitzroy. Carrington’s 600m loop includes steep metal stairs; choose the outing rather than adding every waterfall.',
ps('fitzroy','carrington','nellies'), [('https://www.nationalparks.nsw.gov.au/things-to-do/lookouts/fitzroy-falls-lookout','Fitzroy access and lookout'),('https://www.nationalparks.nsw.gov.au/things-to-do/walking-tracks/carrington-falls-walking-track','Carrington stairs and loop'),('https://weareexplorers.co/southern-highlands-road-trip/','Waterfall alternatives')],variant='base')

day('ext-1','Wed 30 Dec',7,'Across the high country to Tumut','Tumut · 1 of 2 nights','Scenic transfer + short river stroll','Jindabyne → Adaminaby → Tumut · allow about 3½–4½ hr driving',[
('Morning','Leave Jindabyne and take the Snowy Mountains Highway route via Adaminaby, with food, fuel and rest breaks.'),
('Afternoon','Continue to Tumut and check into a motel or ensuite cabin. Keep today as a transfer rather than squeezing in the caves.'),
('Later','Take a short Tumut River walk from town if everyone has energy, then enjoy an easy dinner.')],
'This replaces the 30 December drive to the Southern Highlands. It adds a new base and moves your return to 2 January. Check road conditions and keep the mountain driving in daylight.',
ps('tumut','tumut','yarrangobilly'), [('https://www.visitnsw.com/destinations/snowy-mountains/tumut-area/tumut','Tumut and the river'),('https://www.nationalparks.nsw.gov.au/things-to-do/driving-routes/snowy-mountains-highway','Snowy Mountains Highway')],variant='extended')
days[-1]['images'][1]=photos['tumut'][1]

day('ext-2','Thu 31 Dec',8,'Yarrangobilly caves and thermal pool','Tumut · 2 of 2 nights','Cave steps + very steep pool walk','Tumut ↔ Yarrangobilly · about 2½–3 hr driving return; a full-day outing',[
('Morning','Drive to Yarrangobilly and visit the cave experience confirmed as suitable for your baby and carrier. South Glory is self-guided, with 206 steps inside plus the approach track.'),
('Midday','Picnic in the valley and allow an unhurried rest before deciding on the pool walk.'),
('Afternoon','Visit the spring-fed thermal pool if the walk and conditions suit, then return to Tumut. A cave-only or pool-only outing is a valid scaled-down day.')],
'The thermal pool is around 27°C, reached by a very steep 700m one-way walk, Grade 4. The main pool is 2.5m deep, with a separate wading pool. South Glory is about 10°C and damp, with a 500m approach and a 470m cave route. Confirm carrier clearance, infant arrangements and tour availability with the visitor centre before booking; a backpack carrier can be awkward in caves.',
[photos['yarrangobilly'][0],photos['yarrangobilly'][1],photos['tumut'][0]], [('https://www.nationalparks.nsw.gov.au/things-to-do/show-caves/yarrangobilly-south-glory-cave','South Glory steps and cave conditions'),('https://www.nationalparks.nsw.gov.au/things-to-do/walking-tracks/yarrangobilly-caves-thermal-pool-walk','Thermal pool walk'),('https://www.nationalparks.nsw.gov.au/things-to-do/visitor-centres/yarrangobilly-caves-visitor-centre','Contact and booking advice')],variant='extended')

day('ext-3','Fri 1 Jan',9,'Tumut to the Southern Highlands','Southern Highlands · 1 night','Travel day + village meal','About 3½–4½ hr driving · plus breaks',[
('Morning','Leave Tumut and head towards the Hume Highway. Stop for lunch and time out of the car around Gundagai or Goulburn.'),
('Afternoon','Continue to your selected Berrima, Bowral or Mittagong accommodation.'),
('Evening','Have an easy meal and prepare for tomorrow’s waterfall stop.')],
'New Year’s Day can affect meals, check-in and shops. Confirm your accommodation’s arrival arrangements and bring food as a backup.',
ps('tumut','goulburn','highlands'), [('https://www.visitnsw.com/destinations/country-nsw/southern-highlands','Southern Highlands')],variant='extended')

day('ext-4','Sat 2 Jan',10,'Fitzroy Falls and the return to Sydney','Home · no overnight','Short lookout or optional waterfall half-day','About 2–3 hr driving for the simple route · plus stops',[
('Morning','Visit Fitzroy Falls for the easiest big-waterfall viewpoint, just 150m from the visitor centre.'),
('Alternative','Choose Carrington Falls and Nellies Glen instead for a longer half-day. The Carrington loop has steep metal stairs.'),
('After lunch','Return to Sydney, taking another rest break if needed.')],
'The extended route includes both Yarrangobilly and Tumut without removing your Canberra or Jindabyne nights. It still leaves Rainbow Lake and Porcupine Rocks as a choice unless you combine them or add another mountain night.',
ps('fitzroy','carrington','nellies'), [('https://www.nationalparks.nsw.gov.au/things-to-do/lookouts/fitzroy-falls-lookout','Fitzroy Falls'),('https://www.nationalparks.nsw.gov.au/things-to-do/walking-tracks/carrington-falls-walking-track','Carrington Falls')],variant='extended')

def render_day(d):
    hidden=' hidden' if d['variant']=='extended' else ''
    swap=f'<aside class="swap"><strong>{e(d["swap"][0])}</strong><p>{e(d["swap"][1])}</p></aside>' if d['swap'] else ''
    return f'''<article class="day" id="{d['id']}" data-variant="{d['variant']}"{hidden}>
<div class="day-heading-layout"><div><span class="date-line">{d['date']} · Day {d['num']}</span><h3>{e(d['title'])}</h3></div><aside class="day-heading-meta"><div class="header-weather"><span class="header-meta-label">Walking and pace</span>{e(d['effort'])}</div><div class="header-stay"><span class="header-meta-label">Overnight</span>{e(d['stay'])}</div></aside></div>
{gallery(d['images'],d['title']+' photographs')}<p class="drive">{e(d['drive'])}</p><ul class="schedule">{''.join('<li><strong>'+e(k)+':</strong> '+e(v)+'</li>' for k,v in d['items'])}</ul><p class="day-note">{e(d['note'])}</p>{swap}<div class="links">{''.join(a(url,label) for url,label in d['links'])}{maps(d['title'].split(',')[0])}</div></article>'''

def jump(d):
    return f'<li data-variant="{d["variant"]}"'+(' hidden' if d['variant']=='extended' else '')+f'><a href="#{d["id"]}"><img src="{e(d["images"][0]["url"],quote=True)}" loading="lazy" alt="" width="88" height="66"><span class="index-copy"><time>{d["date"]} · Day {d["num"]}</time><strong>{e(d["title"])}</strong></span><span class="index-arrow" aria-hidden="true">›</span></a></li>'

checklist=[('Choose the return route','31 Dec via the Highlands, or 2 Jan with Tumut and Yarrangobilly. Add another Jindabyne night if you want both lake and rocks walks on separate days.'),('Book accommodation with a private bathroom','Canberra 24–25 Dec; Jindabyne 26–29 Dec; Highlands 30 Dec. For the extension: Tumut 30–31 Dec, Highlands 1 Jan. Confirm cot, parking, kitchen and minimum stays.'),('Book Questacon general admission','26 Dec morning. Check Mini Q peak-period session arrangements and allow time for lunch before the drive south.'),('Confirm Thredbo infant and carrier arrangements','Check the exact lift, loading procedure, operating dates and last return time before buying tickets.'),('Confirm cave and pool plans','If extending, ask Yarrangobilly Visitor Centre about the baby, carrier clearance, cave steps and current tour bookings.'),('Buy Christmas supplies on 24 December','Food, feeding supplies, nappies and drinking water. Reserve any Christmas meal and check reception opening hours.'),('Recheck roads, trails and mountain weather','Use NPWS, Parks ACT, BOM and Live Traffic NSW. Swap the three mountain days around for conditions.'),('Pack for the carrier and summer mountains','Warm and waterproof layers for both of you, sun protection, water, meals, nappies and offline route information. Allow frequent breaks out of the restraint.')]

checklist.append(('Optional balloon flight: confirm the date and childcare', 'Ask Balloon Aloft Canberra about 25 December service, or a 26 December backup, the exact meeting time, date-specific fare and weather cancellation terms. Minimum age 6; arrange a non-flying adult for your baby. Flight tickets and breakfast are extra to the trip budget.'))

all_photos={p['url']:p for d in days for p in d['images']}
for key in ['civic','newacton','kingston','zoo','tidbinbilla','arboretum','rainbow','porcupine','fitzroy','yarrangobilly','tumut','balloon']:
    all_photos.update({p['url']:p for p in photos[key]})

